fn port(raw: &str) -> Option<u16> {
    raw.trim().parse::<u16>().ok().filter(|p| *p > 0)
}
let squares: Vec<i32> = (1..=10)
    .filter(|n| n % 2 == 0)
    .map(|n| n * n)
    .collect();
let p = port(" 8080 ").and_then(|p| p.checked_add(1)).or_else(|| Some(80));

