use nom::{IResult, Parser};
use nom::branch::alt;
use nom::bytes::complete::tag;
use nom::multi::many1;
fn names(input: &str) -> IResult<&str, Vec<&str>> {
    many1(alt((tag("abc"), tag("def")))).parse(input)
}

